    boolean isInSet = false;
    for (int i = 0; i < Set.Length; i++) {
        if (Set[i] == val) {
            isInSet = true;
            break;
        }
    }

    // If the value is in the set, remove it
    if (isInSet) {
        Set.Remove(val);
    }

    // Return whether the set contained the element
    return isInSet;
}

