public void write(final byte[] b, final int off, final int len) throws IOException {
    if (off < 0 || off > b.length) {
        throw new IndexOutOfBoundsException("Offset out of bounds: " + off);
    }
    if (off + len > b.length) {
        throw new IndexOutOfBoundsException("Length out of bounds: " + len);
    }
    if (len < 0) {
        throw new IllegalArgumentException("Length cannot be negative: " + len);
    }
    if (len == 0) {
        return;
    }

    // Write the data to the output stream
    int bytesWritten = 0;
    while (bytesWritten < len) {
        int bytesAvailable = Math.min(len - bytesWritten, outputStream.available());
        outputStream.write(b, off + bytesWritten, bytesAvailable);
        bytesWritten += bytesAvailable;
    }
}

