        if (Modifier.isStatic(writeMethod.getModifiers())) {
            throw new IllegalArgumentException("Can't write to a static property [" + propertyName + "]");
        }
        Object value = readMethod.invoke(map.getBean(), readMethod.getName());
        writeMethod.invoke(getBean(), writeMethod.getName(), value);
    }
}

