private int parseEndOfLine(String headerPart, int end) {

    // Define variables
    int currentIndex = end;
    int lineEndIndex = -1;

    // Check if the end of the line has been reached
    while (currentIndex < headerPart.length() && lineEndIndex == -1) {
        currentIndex++;
        if (headerPart.substring(currentIndex, currentIndex + 2).equals("\r\n")) {
            lineEndIndex = currentIndex;
        }
    }

    // If the end of the line has not been reached, return -1
    if (lineEndIndex == -1) {
        return -1;
    }

    // Return the index of the end of the line
    return lineEndIndex;
}

