public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {

    // Check if the input string is null or empty
    if (str == null || str.isEmpty()) {
        return false;
    }

    // Check if the search string array is null or empty
    if (searchStrArray == null || searchStrArray.isEmpty()) {
        return false;
    }

    // Convert the input string to lowercase
    String strLower = str.toLowerCase();

    // Iterate over the search string array
    for (String searchStr : searchStrArray) {

        // Check if the search string is null or empty
        if (searchStr == null || searchStr.isEmpty()) {
            continue;
        }

        // Convert the search string to lowercase
        String searchStrLower = searchStr.toLowerCase();

        // Check if the input string contains the search string
        if (strLower.contains(searchStrLower)) {
            return true;
        }
    }

    // The input string does not contain any character in the search string array
    return false;
}

