private Set<V> intersection(Set<V> set1, Set<V> set2) {
  // If either set is empty, return an empty set
  if (set1.isEmpty() || set2.isEmpty()) {
    return Collections.emptySet();
  }

  // If the sets are equal, return one of them
  if (set1.equals(set2)) {
    return set1;
  }

  // Compute the intersection by iterating over the elements of set1
  // and checking if they are in set2
  Set<V> intersection = new HashSet<>();
  for (V element : set1) {
    if (set2.contains(element)) {
      intersection.add(element);
    }
  }

  return intersection;
}

