    // Initialize the circulator to the starting node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);

    // If the starting node is the stop node, just return it
    if (stop.getId() == start.getId()) {
        return circulator;
    }

    // Traverse the boundary of the component in the specified direction
    while (circulator.hasNext() && circulator.next() != stop) {
        if (predicate.test(circulator.getNode())) {
            // If a node satisfying the predicate is found, return the circulator to that node
            return circulator;
        }
    }

    // If no node satisfying the predicate is found, return the circulator to the stop node
    return new OuterFaceCirculator(stop);
}

