private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    // Step 1: Validate input and initialize variables
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("bounds list must not be null or empty");
    }
    int count = bounds.size();
    List<Integer> suffixSums = new ArrayList<>(count);
    long sum = 0;

    // Step 2: Compute suffix sum
    for (int i = 0; i < count; i++) {
        Integer bound = bounds.get(i);
        if (bound == null) {
            throw new IllegalArgumentException("bounds list must not contain null elements");
        }
        suffixSums.add(bound);
        sum += bound;
    }

    // Step 3: Compute total sum and return result pair
    return new Pair<>(suffixSums, sum);
}

