private List<Integer> computeLowerBounds(List<K> keys) {
    // Initialize a list to store the computed key lower bounds
    List<Integer> lowerBounds = new ArrayList<Integer>();

    // If the number of keys is 0 or 1, return an empty list
    if (keys.size() <= 1) {
        return lowerBounds;
    }

    // Initialize the first lower bound to the first key
    lowerBounds.add(keys.get(0));

    // Iterate over the remaining keys and update the lower bound for each key
    for (int i = 1; i < keys.size(); i++) {
        K currentKey = keys.get(i);
        int currentLowerBound = Collections.binarySearch(lowerBounds, currentKey);
        if (currentLowerBound < 0) {
            currentLowerBound = -(currentLowerBound + 1);
        }
        lowerBounds.add(currentLowerBound, currentKey);
    }

    return lowerBounds;
}

