        String[] params = queryParams[1].split("&");
        for (int i = 0; i < params.length; i++) {
            String[] keyValue = params[i].split("=");
            if (keyValue.length == 2) {
                query.put(URLDecoder.decode(keyValue[0], StandardCharsets.UTF_8), URLDecoder.decode(keyValue[1], StandardCharsets.UTF_8));
            }
