public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder unescaped = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i == str.length() - 1) {
                throw new Exception("Illegal escape character at end of string");
            }
            c = str.charAt(++i);
            if (c == 'n') {
                unescaped.append("\n");
            } else if (c == 'r') {
                unescaped.append("\r");
            } else if (c == 't') {
                unescaped.append("\t");
            } else if (c == 'b') {
                unescaped.append("\b");
            } else if (c == 'f') {
                unescaped.append("\f");
            } else if (c == 'u') {
                if (i >= str.length() - 4) {
                    throw new Exception("Illegal Unicode escape sequence at end of string");
                }
                String unicodeHex = str.substring(i + 1, i + 5);
                try {
                    int unicodeValue = Integer.parseInt(unicodeHex, 16);
