public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Check if there is a direct bound on the type variable
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length > 0) {
        return bounds[0];
    }
    // If there is no direct bound, try to find the bound for the type variable's declaring class
    Class<?> declaringClass = typeVariable.getDeclaringClass();
    if (declaringClass != null) {
        Type[] superclassBounds = declaringClass.getBounds();
        if (superclassBounds.length > 0) {
            return superclassBounds[0];
        }
    }
    // If we couldn't find a bound, return Unknown.class
    return Unknown.class;
}

