List<String> relativePathList = new ArrayList<>(Arrays.asList(relativePath.split("/")));

for (String part : relativePathList) {
if (part.equals("..")) {
pathList.remove(pathList.size() - 1);
} else if (!part.isEmpty() && !part.equals(".")) {
pathList.add(part);
}
}

return String.join("/", pathList);
}

