List<TimeRange> buildTimeRanges(long start, long end) {
    final long maxRangePeriod = FETCH_DATA_DURATION;
    List<TimeRange> timeRanges = new ArrayList<>();
    // If the start time is within the max range period, split it
    if (start < end && end - start > maxRangePeriod) {
        long splitStart = start;
        long splitEnd = start + maxRangePeriod;
        while (splitEnd < end) {
            timeRanges.add(new TimeRange(splitStart, splitEnd));
            splitStart = splitEnd + 1;
            splitEnd = Math.min(splitStart + maxRangePeriod, end);
        }
    }
    else {
        timeRanges.add(new TimeRange(start, end));
    }
    return timeRanges;
}

